import sys

def solve():
    N = int(sys.stdin.readline())
    K = int(sys.stdin.readline())
    x = list(map(int, sys.stdin.readline().split()))

    min_distance = float('inf')

    for a in range(N):
        for b in range(N):
            distance = 0
            for i in range(N):
                if i == a:
                    distance += 2 * (x[i] + 1)
                elif i == b:
                    distance += 2 * (K - x[i] + 1)
                else:
                    distance += min(2 * (x[i] + 1), 2 * (K - x[i] + 1))
            min_distance = min(min_distance, distance)

    print(min_distance)

if __name__ == "__main__":
    solve()
